iglesias = ["Éfeso", "Esmirna", "Pérgamo", "Tiatira", "Sardis", "Filadelfia", "Laodicea"]

for n, iglesia in enumerate(iglesias[:3], start=1):
    print(n, iglesia)

it = iter(iglesias)
print(next(it), next(it))          # Éfeso Esmirna

def largas(nombres):
    for nombre in nombres:
        if len(nombre) > 7:
            yield nombre               # se pausa aquí hasta el próximo next()

print(list(largas(iglesias)))
print(sum(len(n) for n in iglesias))
print(any(n.startswith("S") for n in iglesias), all(n.istitle() for n in iglesias))

