def long_names(names):
    for name in names:
        if len(name) > 7:
            yield name                 # it pauses here until the next next()

print(list(long_names(churches)))
print(sum(len(n) for n in churches))
print(any(n.startswith("S") for n in churches), all(n.istitle() for n in churches))

